def analyze_band_for_test(rmin, rmax, grid):
    left_counts = [0] * 9
    right_counts = [0] * 9
    for r in range(rmin, min(rmax+1, 19)):
        for c in range(16):  # 0-15, 2-wide blocks (17 cols, so 16 possible 2-block positions)
            block_top = grid[r][c:c+2]
            if r+1 < 19:
                block_bot = grid[r+1][c:c+2]
                if any(cell in [1, 7] for row in [block_top, block_bot] for cell in row):  # Test uses 1s and 7s
                    if c < 9:
                        left_counts[c] += 1
                    else:
                        right_counts[c-9] += 1
            else:
                if any(cell in [1, 7] for cell in block_top):
                    if c < 9:
                        left_counts[c] += 1
                    else:
                        right_counts[c-9] += 1
    return left_counts, right_counts

